import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

export default function AddCamera({ token }) {
  const [name, setName] = useState('');
  const [locationType, setLocationType] = useState('home');
  const [rtspUrl, setRtspUrl] = useState('');
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const handleAdd = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/cameras', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ name, locationType, rtspUrl })
      });
      if (res.ok) navigate('/dashboard');
      else setError('Failed to add camera stream.');
    } catch (err) {
      setError('Backend communication error.');
    }
  };

  return (
    <div style={{ maxWidth: '550px', margin: '0 auto' }}>
      <div className="card">
        <h2 style={{ marginBottom: '1.5rem', color: '#38bdf8' }}>Connect New CCTV Stream</h2>
        {error && <div className="message-banner error">{error}</div>}
        <form onSubmit={handleAdd}>
          <div className="form-group">
            <label>Camera Name</label>
            <input type="text" placeholder="e.g. Entrance Highway Cam" value={name} onChange={e => setName(e.target.value)} required />
          </div>
          <div className="form-group">
            <label>Location Type</label>
            <select value={locationType} onChange={e => setLocationType(e.target.value)}>
              <option value="home">Home</option>
              <option value="road">Road</option>
              <option value="college">College</option>
              <option value="mall">Mall</option>
              <option value="railway station">Railway Station</option>
              <option value="others">Others</option>
            </select>
          </div>
          <div className="form-group">
            <label>RTSP Stream Address</label>
            <input type="text" placeholder="rtsp://192.168.1.100:554/stream" value={rtspUrl} onChange={e => setRtspUrl(e.target.value)} required />
          </div>
          <button type="submit" className="btn-primary">Add Camera Stream</button>
        </form>
      </div>
    </div>
  );
}
